"""

MESSY = """#pragma once

struct Point {
\tint x;
    int y;
};

int distance_squared(const Point& a, const Point& b) {
    int dx = a.x - b.x;   
    int dy = a.y - b.y;
    int dz = dx * dx + dy * dy + a.x + b.x + a.y + b.y + dx + dy + 12345;
    return dx * dx + dy * dy;
}
"""

STYLE = [
    ("ST001", "行宽不得超过 80 列"),
    ("ST002", "禁止用 Tab 缩进（统一 4 空格）"),
    ("ST003", "禁止行尾空白"),
    ("ST004", "缩进必须是 4 空格的整数倍"),
    ("ST005", "关键字 if/for/while 后必须有空格"),
]


def lint(text, width=80):
    issues = []
    for no, raw in enumerate(text.splitlines(), 1):
        if len(raw) > width:
            issues.append(("ST001", no, "行宽 %d > %d" % (len(raw), width)))
        if raw.startswith("\t") or "\t" in raw[:len(raw) - len(raw.lstrip())]:
            issues.append(("ST002", no, "缩进使用了 Tab"))
        if raw != raw.rstrip():
            issues.append(("ST003", no, "行尾有多余空白"))
        indent = len(raw) - len(raw.lstrip(" "))
        if raw.strip() and indent % 4 != 0:
            issues.append(("ST004", no, "缩进 %d 不是 4 的倍数" % indent))
        for kw in ("if", "for", "while"):
            if (kw + "(") in raw and not raw.lstrip().startswith("//"):
                issues.append(("ST005", no, "关键字 %s 后缺少空格" % kw))
    issues.sort()
    return issues


for label, text, want_clean in (("正例 formatted.cpp", FORMATTED, True), ("反例 messy.cpp", MESSY, False)):
    issues = lint(text)
    print("[%s] 行数=%d 问题=%d" % (label, len(text.splitlines()), len(issues)))
    for code, no, msg in issues:
        print("  %s 第%d行 %s" % (code, no, msg))
    assert (not issues) == want_clean, "判定与预期不符: " + label

print("[规则库] %s" % " / ".join("%s %s" % (c, d) for c, d in STYLE))
